from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class CrossSectionalMomentum(Strategy):
    rationale = (
        "Cross-sectional momentum exploits the tendency of stocks with strong recent "
        "performance to continue outperforming. This strategy selects the top-performing "
        "stocks over a lookback period and allocates capital accordingly."
    )

    def __init__(self, window: int = 20, top_n: int = 5) -> None:
        self._window = window
        self._top_n = top_n

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window * len(view.symbols):
            return Signal(information_available_at=stamp, weights={})

        returns = (
            history.select(pl.col("adj_close").change().alias("return"))
            .group_by("symbol")
            .agg(pl.col("return").mean().alias("avg_return"))
            .sort("avg_return", descending=True)
            .select("symbol", "avg_return")
            .head(self._top_n)
        )

        symbols = [row.symbol for row in returns.iter_rows()]
        weights = {s: 1.0 / len(symbols) for s in symbols}
        return Signal(information_available_at=stamp, weights=weights)


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
